				/>
				<Route path="/game" element={<GamePage />} />
			</Routes>,
			{ game },
			{ route: "/game" },
		);

		// Start (default count 2), rate one item, abandon mid-round.
		startRound();
		reveal();
		rate(/Again/);
		fireEvent.click(screen.getByRole("button", { name: "End round" }));
		expect(screen.getByText("Dashboard home")).toBeTruthy();
