					<Routes>
						<Route path="/game" element={<GamePage />} />
					</Routes>
				</MemoryRouter>
			</AppProvider>,
		);

		fireEvent.click(screen.getByLabelText("Words"));
		setCount("2");
		startRound();
		for (const rating of [/Again/, /Good/]) {
			reveal();
			rate(rating);
		}
